const menu = document.querySelector('.menu');
const nav = document.querySelector('nav');
menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Fechar menu' : 'Abrir menu'); nav.classList.toggle('open', open); });
nav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Abrir menu'); }));
function estimate() { const ids = ['phones','lights','days']; const values = ids.map(id => { const input = document.getElementById(id); const n = Number(input.value); return Number.isFinite(n) ? Math.min(Number(input.max), Math.max(Number(input.min), n)) : Number(input.min); }); const [phones, lights, days] = values; const wh = Math.ceil((phones * 15 + lights * 9 * 4) * days / .85 * 1.2); document.getElementById('energy').textContent = wh.toLocaleString('pt-BR') + ' Wh'; }
document.querySelectorAll('.calculator input').forEach(input => { input.addEventListener('input', estimate); input.addEventListener('change', () => { input.value = String(Math.min(Number(input.max), Math.max(Number(input.min), Number(input.value) || Number(input.min)))); estimate(); }); });
estimate();
document.getElementById('copy-pix').addEventListener('click', async () => { const key = document.getElementById('pix'); const status = document.getElementById('copy-status'); status.textContent = 'Copiando chave…'; try { await Promise.race([navigator.clipboard.writeText(key.value), new Promise((_, reject) => setTimeout(() => reject(new Error('clipboard timeout')), 1500))]); status.textContent = 'Chave copiada. Confira o beneficiário no seu banco.'; } catch { key.focus(); key.select(); status.textContent = 'Selecione e copie a chave acima para usar no seu banco.'; } });
document.getElementById('year').textContent = String(new Date().getFullYear());



document.querySelectorAll('.ux-app').forEach(app => { app.querySelectorAll('[data-go]').forEach(button => button.addEventListener('click', () => { const target = button.dataset.go; app.querySelectorAll('[data-view]').forEach(view => view.classList.toggle('active',view.dataset.view === target)); app.querySelectorAll('.ux-nav [data-go]').forEach(nav => { const section = ['adicionar','qr','convite','proximos','privacidade'].includes(target) ? 'conversas' : ['cidade','biblia','saude','cofre','preparar'].includes(target) ? 'mais' : target; const active = nav.dataset.go === section; nav.classList.toggle('active',active); nav.setAttribute('aria-pressed',String(active)); }); app.querySelector('.ux-content').scrollTop=0; })); });
document.querySelectorAll('.ux-app').forEach(app => { app.querySelectorAll('[data-context]').forEach(button => button.addEventListener('click', () => { app.querySelectorAll('[data-context]').forEach(tab => { const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active)); }); app.querySelectorAll('[data-pane]').forEach(pane=>pane.classList.toggle('active',pane.dataset.pane===button.dataset.context)); })); });
